// Auto-generated ultra-lightweight progressive blur-up placeholders (24x16 JPEG base64)
// Standard Core Web Vitals technique for instantaneous visual feedback without layout shift

export const blurDataMap: Record<string, string> = {
  "/spatial-campus-hero.jpg": "data:image/jpeg;base64,",
  "/spatial-campus-hero-mobile.jpg": "data:image/jpeg;base64,",
  "/ilya-author.jpg": "data:image/jpeg;base64,",
  "/criteria-essay.jpg": "data:image/jpeg;base64,",
  "/criteria-video.jpg": "data:image/jpeg;base64,",
  "/criteria-resume.jpg": "data:image/jpeg;base64,",
  "/criteria-zoom.jpg": "data:image/jpeg;base64,",
  "/stage-01.jpg": "data:image/jpeg;base64,",
  "/stage-02.jpg": "data:image/jpeg;base64,",
  "/stage-03.jpg": "data:image/jpeg;base64,",
  "/stage-04.jpg": "data:image/jpeg;base64,",
  "/stage-05.jpg": "data:image/jpeg;base64,"
};

const DEFAULT_BLUR =
  "data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Crect width='100%25' height='100%25' fill='%2312161f'/%3E%3C/svg%3E";

export function getBlurDataURL(src: string | undefined): string {
  if (!src) return DEFAULT_BLUR;
  const cleanSrc = src.split('?')[0];
  return blurDataMap[cleanSrc] || DEFAULT_BLUR;
}
